(() => {
  'use strict';
  const D = window.ATLAS;
  const institutions = new Map(D.institutions.map(i => [i.id, i]));
  const programs = new Map(D.programs.map(p => [p.id, p]));
  const selected = new Set();
  const main = document.querySelector('main');
  const dialog = document.querySelector('#detail');
  const pay = {salary:'Salario',grant:'Beca / ayuda',unpaid:'Sin remuneración',varies:'Depende de la vía',unknown:'Pago por confirmar'};
  const stage = {pre:'Antes del PhD',phd:'Ya en el PhD',experiencia:'Con experiencia',grado:'Durante el grado'};
  const priority = {1:'Primera jugada',2:'Buena alternativa',3:'Según tu tema',4:'Otra etapa'};
  const kind = {programa:'Programa documentado',canal:'Contratación por equipo',destino:'Destino de otro programa'};
  const E = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = v => String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const link = (url,label,cls='') => `<a href="${E(url)}" target="_blank" rel="noopener noreferrer" class="${E(cls)}">${E(label)} ↗</a>`;
  const options = (items,chosen,all) => `<option value="">${E(all)}</option>`+items.map(([v,l])=>`<option value="${E(v)}" ${chosen===v?'selected':''}>${E(l)}</option>`).join('');
  const countries = [...new Set(D.institutions.map(i=>i.country))].sort((a,b)=>a.localeCompare(b,'es'));
  const groupName = id => D.groups.find(g=>g.id===id)?.short ?? id;
  const params = () => new URLSearchParams(location.hash.split('?')[1] || '');
  const path = () => (location.hash.slice(1).split('?')[0] || 'guia');
  let returnHash = '#explorar';
  let closing = false;
  let toastTimer;
  let detailOrigin = '';
  let detailScroll = 0;
  let restoreDetailFocus = false;

  function notify(message) {
    const el = document.querySelector('#toast'); el.textContent=message; el.classList.add('visible');
    clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);
  }
  function updateNav() {
    const current = path().split('/')[0];
    document.querySelectorAll('[data-nav]').forEach(a=>a.toggleAttribute('aria-current',false));
    const active=document.querySelector(`[data-nav="${['guia','explorar','comparar','criterio'].includes(current)?current:'explorar'}"]`);
    active?.setAttribute('aria-current','page');
    document.querySelector('#compare-nav-count').textContent=selected.size?`(${selected.size})`:'';
  }
  function compareButton(p) {
    const yes=selected.has(p.id);
    return `<button class="compare-add" data-compare="${E(p.id)}" aria-pressed="${yes}" aria-label="${yes?'Quitar de':'Añadir a'} comparación: ${E(p.name)}">${yes?'✓ Añadido':'+ Comparar'}</button>`;
  }
  function tray() {
    return selected.size?`<div class="compare-tray"><p><strong>${selected.size} de 3</strong> rutas seleccionadas. Compáralas con calma.</p><a href="#comparar" class="button coral small">Ver comparación →</a></div>`:'';
  }
  function card(p) {
    const i=institutions.get(p.institution);
    return `<article class="program-card"><p class="eyebrow">${E(groupName(p.group))} · ${E(p.country)}</p><div><span class="badge ${p.priority===4?'later':''}">${priority[p.priority]}</span><span class="badge subtle">${stage[p.stage]}</span></div><h2><a href="#programa/${E(p.id)}">${E(p.name)}</a></h2><p class="institution-name"><a href="#institucion/${E(i.id)}">${E(i.name)}</a></p><p>${E(p.fit)}</p><div class="card-meta"><div><span>Duración</span>${E(p.duration)}</div><div><span>Condiciones</span>${pay[p.pay]}</div></div><div class="card-actions"><a href="#programa/${E(p.id)}">Ver la ficha →</a>${compareButton(p)}</div></article>`;
  }

  function renderGuide() {
    const q=params(), family=q.get('familia')||'investigacion', country=q.get('pais')||'';
    const g=D.groups.find(g=>g.id===family)||D.groups[0];
    const list=D.institutions.filter(i=>i.group===g.id&&(!country||i.country===country));
    main.innerHTML=`<section class="hero"><div class="hero-inner"><div><p class="eyebrow">El mapa antes del PhD · Oxford / LSE</p><h1>Un mundo de siglas.<br><em>Vamos al grano.</em></h1><p class="hero-copy">Quieres investigar cómo funciona la sociedad con datos. Bien. Ahora toca saber dónde puedes aprender a hacerlo en serio, quién manda en cada terreno y qué programa merece tu tiempo.</p><a class="button coral" href="#explorar">Encuentra tu siguiente jugada →</a><span class="hero-note">Rutas recurrentes y equipos de investigación. Tú consultas las plazas.</span></div><aside class="recommendation"><p class="eyebrow">Si un amigo se hubiera estudiado el mapa</p><h3>Yo empezaría por aquí.</h3><a class="rank-link" href="#institucion/lse"><strong>01 / LSE & IFS · una RA con chicha</strong><span>Métodos, investigación empírica y una referencia que te haya visto trabajar.</span></a><a class="rank-link" href="#institucion/jp"><strong>02 / J-PAL & DIME · aprende a evaluar</strong><span>Si lo tuyo es causalidad, desarrollo o desigualdad, tienen mucho sentido.</span></a><a class="rank-link" href="#institucion/oecd"><strong>03 / OCDE · datos que hablan con gobiernos</strong><span>Una marca fuerte en policy. Elige unidad y tareas con lupa.</span></a><a class="rank-link" href="#institucion/mpidr"><strong>La tapada / Max Planck · población + datos</strong><span>El Summer Incubator es una ruta corta y muy concreta. Mira la matrícula exigida.</span></a><p class="legal-note">Mi orden editorial para preparar investigación. Tu tema puede darle la vuelta.</p></aside></div></section><div class="stat-strip"><span><strong>${D.institutions.length}</strong> instituciones</span><span><strong>${D.programs.length}</strong> rutas documentadas</span><span><strong>${D.groups.length}</strong> familias para orientarte</span><span>Edición 30/09/2026</span></div><section class="wrap"><div class="section-top"><div><p class="eyebrow">Primero, entiende el terreno</p><h2>¿Quién pinta qué?</h2><p>Siete familias. Dentro de cada una, líderes, alternativas y diferencias que importan.</p></div><p class="intro-note">No hay una liga única de prestigio. Un economista, una investigadora de redes y un equipo de policy valoran cosas distintas.</p></div><div class="tribes">${D.groups.map((x,n)=>`<button class="tribe ${n===6?'wide':''}" style="--tribe-color:${x.color}" data-family="${x.id}" aria-pressed="${x.id===g.id}"><span class="eyebrow">0${n+1} / ${E(x.tag)}</span><h3>${E(x.short)}</h3><p>${E(x.lead)}</p></button>`).join('')}</div><section class="guide-panel" id="familia"><p class="eyebrow">${E(g.tag)}</p><h3>${E(g.name)}</h3><div class="guide-intro"><p>${E(g.text)}</p><aside><p>${E(g.comparison)}</p></aside></div><div class="toolbar" style="margin-top:24px"><label for="guide-country">País / ámbito</label><select id="guide-country">${options(countries.map(c=>[c,c]),country,'Todos los países / ámbitos')}</select><a href="#explorar?familia=${g.id}&etapa=pre" class="button small">Ver sus rutas →</a></div><p class="legal-note">El filtro usa el ámbito declarado por la institución. «Global» y los ámbitos de varios países tienen su propia opción; el lugar concreto aparece en cada ficha.</p><div class="institutions">${list.length?list.map(i=>`<article class="institution-card"><p class="meta">${E(i.country)} · ${E(i.city)}</p><h4>${E(i.name)}</h4><p>${E(i.verdict)}</p><a href="#institucion/${i.id}">Qué es, por qué importa y sus rutas →</a></article>`).join(''):'<div class="empty"><p>Esta familia no tiene instituciones documentadas en ese ámbito.</p><button data-country-reset>Ver todos los ámbitos</button></div>'}</div></section></section><section class="band"><div class="band-inner"><h2>La marca mola.<br>¿Qué vas a investigar?</h2><p>Para el PhD, busca una pregunta social, una contribución que puedas explicar y alguien que conozca cómo investigas. Eso te da material para la propuesta, la muestra escrita y las referencias. Una RA pequeña puede darte más que unas prácticas famosas con tareas administrativas.</p></div></section>`;
    const change=()=>{ const s=new URLSearchParams({familia:g.id});const value=document.querySelector('#guide-country').value;if(value)s.set('pais',value);location.hash='guia?'+s;};
    document.querySelector('#guide-country').addEventListener('change',change);
    document.querySelector('[data-country-reset]')?.addEventListener('click',()=>location.hash='guia?familia='+g.id);
  }

  function renderExplorer() {
    const q=params(); const currentStage=q.has('etapa')?q.get('etapa'):'pre';
    const type=q.get('tipo')||'programa';
    main.innerHTML=`<section class="explorer-head"><div><div><p class="eyebrow">Programas, destinos y contratación</p><h1>Vamos a lo concreto.</h1><p>Busca por tema, institución o país. Abre la ficha para entender los requisitos y añade hasta tres rutas a la comparación.</p></div></div></section><section class="wrap"><div class="tabs" aria-label="Tipo de ruta">${[['programa','Programas & destinos'],['canal','Contratación por equipo'],['todo','Todo el mapa']].map(([v,l])=>`<button data-type="${v}" aria-pressed="${type===v}">${l}</button>`).join('')}</div><form id="search-form"><div class="searchbar"><label for="search" class="visually-hidden">Buscar programas e instituciones</label><input id="search" type="search" placeholder="Prueba: desigualdad, OCDE, predoc, IA…" value="${E(q.get('q')||'')}" autocomplete="off"><button class="button coral" type="submit">Buscar →</button></div><div class="filters"><div class="field"><label for="family">Familia</label><select id="family">${options(D.groups.map(g=>[g.id,g.short]),q.get('familia'),'Todas las familias')}</select></div><div class="field"><label for="theme">Tu tema</label><select id="theme">${options(Object.entries(D.themes),q.get('tema'),'Todos los temas')}</select></div><div class="field"><label for="country">País / ámbito</label><select id="country">${options(countries.map(c=>[c,c]),q.get('pais'),'Todos los ámbitos')}</select></div><div class="field"><label for="stage">Tu etapa</label><select id="stage">${options(Object.entries(stage),currentStage,'Todas las etapas')}</select></div><div class="field"><label for="pay">Pago</label><select id="pay">${options(Object.entries(pay),q.get('pago'),'Todas las condiciones')}</select></div></div></form><div class="results-top"><p id="results-count" role="status" aria-live="polite"></p><div><span class="order">Orden: encaje editorial con el PhD</span> <button class="quiet" id="reset-filters">Limpiar filtros</button></div></div><div id="results" class="programs"></div><div class="note-box"><p id="type-note"></p></div><div id="tray-slot"></div></section>`;
    let chosenType=type;
    const refresh=(sync=true)=>{
      const state={q:document.querySelector('#search').value.trim(),familia:document.querySelector('#family').value,tema:document.querySelector('#theme').value,pais:document.querySelector('#country').value,etapa:document.querySelector('#stage').value,pago:document.querySelector('#pay').value,tipo:chosenType};
      const terms=normalize(state.q).split(/\s+/).filter(Boolean);
      const list=D.programs.filter(p=>{
        const i=institutions.get(p.institution);
        const hay=normalize([p.name,i.name,i.intro,p.fit,p.eligibility,p.location,p.country,...p.themes.map(t=>D.themes[t])].join(' '));
        return (state.tipo==='todo'||(state.tipo==='programa'?p.kind!=='canal':p.kind==='canal'))&&(!state.familia||p.group===state.familia)&&(!state.tema||p.themes.includes(state.tema))&&(!state.pais||p.country===state.pais)&&(!state.etapa||p.stage===state.etapa)&&(!state.pago||p.pay===state.pago)&&terms.every(t=>hay.includes(t));
      }).sort((a,b)=>a.priority-b.priority||institutions.get(a.institution).name.localeCompare(institutions.get(b.institution).name,'es')||a.name.localeCompare(b.name,'es'));
      const institutionCount=new Set(list.map(p=>p.institution)).size;
      document.querySelector('#results-count').textContent=`${list.length} ${list.length===1?'ruta':'rutas'} · ${institutionCount} ${institutionCount===1?'institución':'instituciones'}${state.etapa?' · '+stage[state.etapa]:''}`;
      document.querySelector('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No sale nada por aquí.</h2><p>Prueba con menos filtros, otra etapa o «Todo el mapa». La búsqueda exige que aparezcan todas las palabras.</p><button data-clear>Limpiar filtros</button></div>';
      document.querySelector('#type-note').textContent=chosenType==='canal'?'Aquí no prometemos un programa fijo: son centros y empresas que contratan por proyectos o equipos. La ficha separa la evidencia de ese canal y el portal donde puedes consultar puestos.':chosenType==='programa'?'Un programa documentado puede cambiar de reglas o no celebrarse una edición. «Destino» identifica una institución que recibe participantes de otro programa, como EEA mediante Blue Book. No se muestra disponibilidad actual.':'Programas formales, destinos y contratación por equipos se distinguen dentro de cada ficha. «Antes del PhD» es una etapa orientativa: lee matrícula, nacionalidad, experiencia e idiomas antes de contar con una vía.';
      document.querySelector('#tray-slot').innerHTML=tray();
      if(sync){const s=new URLSearchParams();Object.entries(state).forEach(([k,v])=>{if(v||k==='etapa')s.set(k,v);});history.replaceState(null,'','#explorar?'+s);}
    };
    document.querySelector('#search').addEventListener('input',()=>refresh());
    document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();refresh();});
    document.querySelectorAll('.filters select').forEach(s=>s.addEventListener('change',()=>refresh()));
    document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{chosenType=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));refresh();}));
    document.querySelector('#reset-filters').addEventListener('click',clearFilters);
    refresh(false);
  }
  function clearFilters() { location.hash='explorar?etapa=&tipo=todo'; if(path()==='explorar')renderExplorer(); }

  function renderCompare() {
    const list=[...selected].map(id=>programs.get(id));
    const rows=[['Mi lectura',p=>priority[p.priority]+'. '+p.fit],['Tipo de ruta',p=>kind[p.kind]],['Etapa',p=>stage[p.stage]],['Requisitos',p=>p.eligibility],['Lugar',p=>p.location],['Duración',p=>p.duration],['Pago',p=>pay[p.pay]],['Recurrencia',p=>p.rhythm],['Ojo con esto',p=>p.watch],['Qué preparar',p=>p.docs]];
    main.innerHTML=`<section class="wrap"><p class="eyebrow">Hasta tres rutas, frente a frente</p><h1>Decide con criterio.</h1><p>Los requisitos y las condiciones vienen de las fuentes enlazadas. La prioridad y el encaje son una lectura editorial para preparar investigación en Social Data Science.</p><div class="toolbar"><a href="#explorar" class="button coral small">Añadir otra ruta →</a>${list.length?'<button class="quiet" data-clear-compare>Vaciar comparación</button>':''}</div>${list.length?`<div class="comparison-scroll" tabindex="0" aria-label="Tabla de comparación; desplazamiento horizontal en pantallas pequeñas"><table class="comparison-table"><caption class="visually-hidden">Comparación de ${list.length} rutas seleccionadas</caption><thead><tr><th scope="col">Qué comparar</th>${list.map(p=>`<th scope="col"><h3><a href="#programa/${E(p.id)}">${E(p.name)}</a></h3><p>${E(institutions.get(p.institution).name)}</p><button class="remove" data-remove="${p.id}">Quitar ${E(p.name)}</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${E(fn(p))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Fuentes y plazas</th>${list.map(p=>`<td>${link(p.url,'Fuente del programa / vía')}<br>${p.portal?link(p.portal,'Portal de contratación'):link(p.url,'Consultar la institución')}</td>`).join('')}</tr></tbody></table></div>`:'<div class="empty"><h2>Elige tus candidatas.</h2><p>En «Programas», pulsa «+ Comparar» en las rutas que te interesen. Puedes ver hasta tres juntas.</p><a class="button coral" href="#explorar">Explorar programas →</a></div>'}<p class="legal-note" style="margin-top:25px">La selección dura mientras esta pestaña siga abierta. No hay cuentas ni seguimiento de vacantes. En móvil, desliza la tabla para ver todas las columnas.</p></section>`;
  }

  function renderCriteria() {
    const sources=new Set([...D.institutions.map(i=>i.url),...D.programs.flatMap(p=>[p.url,p.portal].filter(Boolean)),...D.voices.map(v=>v.url),...D.targets.map(t=>t.url)]);
    main.innerHTML=`<section class="explorer-head"><div><div><p class="eyebrow">Que la confianza tenga fundamento</p><h1>Voces, fuentes y criterio.</h1><p>Una cosa es qué exige un programa. Otra, qué pienso de él. Y otra, lo que cuenta una persona que pasó por allí. Aquí puedes distinguir las tres.</p></div></div></section><section class="wrap"><div class="section-top"><div><h2>Tu norte: Oxford / LSE.</h2><p>El prestigio ayuda a que alguien reconozca un nombre. El trabajo concreto te ayuda a explicar por qué puedes investigar.</p></div></div><div class="criteria-grid"><article class="criteria-card"><p class="eyebrow">DPhil in Social Data Science · OII</p><h2>Oxford: pregunta social, músculo cuantitativo.</h2><p>La página oficial pide una formación académica sólida, normalmente máster con al menos 65% y un grado con el nivel indicado; valora aptitud cuantitativa y una propuesta pertinente al programa. La candidatura incluye muestra escrita y referencias.</p><p>Una publicación puede ser una ventaja. No es un requisito universal. Ninguna de estas prácticas garantiza una plaza.</p>${link('https://www.ox.ac.uk/admissions/graduate/courses/dphil-social-data-science','Requisitos oficiales de Oxford')}</article><article class="criteria-card"><p class="eyebrow">MPhil/PhD Computational Social Science · Methodology</p><h2>LSE: que el método resuelva algo.</h2><p>La descripción oficial pone el foco en base social y computacional, estadística sólida y un proyecto con innovación metodológica o relevancia sustantiva para ciencias sociales. Revisa los requisitos académicos concretos en la página del programa.</p><p>Una RA con diseño de investigación, análisis y escritura suele darte material más directo para esa candidatura. Es nuestra inferencia editorial, no una preferencia de admisión publicada.</p>${link('https://www.lse.ac.uk/study-at-lse/graduate/mphilphd-computational-social-science','Requisitos oficiales de LSE')}</article></div><section class="guide-panel"><p class="eyebrow">Prestigio, ¿para quién?</p><h3>Una marca puede ser gigante en su terreno.</h3><div class="guide-intro"><p><strong>Investigación académica:</strong> LSE, IFS, Max Planck, J-PAL y centros de métodos tienen un encaje legible por su actividad investigadora. El proyecto y la persona que te supervisa son decisivos.</p><aside><p><strong>Policy internacional:</strong> OCDE, Banco Mundial, FMI y organismos de la UE pesan por su papel institucional. <strong>ML:</strong> Microsoft Research y Google Research / DeepMind destacan por su investigación técnica. Son interlocutores distintos.</p></aside></div><p style="margin-top:20px">No hay datos aquí para decir «la gente piensa» de todas las instituciones. Las comparaciones son juicios editoriales basados en misión, tareas y vías documentadas. Cuando hay voces públicas, ves qué tipo de fuente son y qué permiten concluir.</p></section><section style="margin-top:40px"><h2>Cómo leer mis prioridades.</h2><div class="criteria-grid">${Object.entries(priority).map(([n,l])=>`<article class="criteria-card"><span class="badge ${n==='4'?'later':''}">${l}</span><p>${({'1':'Empezaría aquí si el tema encaja: investigación, métodos o policy cuantitativa con una contribución clara. No mide selectividad ni calidad garantizada.','2':'Una alternativa sólida que puede superar a la primera si el equipo, el proyecto o las condiciones te encajan mejor.','3':'Tiene sentido con una pregunta concreta. Puede ser más profesional, operativo o técnico que investigador.','4':'La vía exige otra etapa —por ejemplo, doctorado en curso— o supone un compromiso distinto. Guárdala para el momento adecuado.'})[n]}</p></article>`).join('')}</div><div class="note-box"><p><strong>El orden que usaría al decidir:</strong> pregunta y métodos → supervisión → contribución y muestra escrita → referencias → requisitos y condiciones → nombre de la institución. Antes de aceptar, pregunta qué podrás mostrar, cuánto analizarás y quién revisará tu trabajo.</p></div></section></section><section class="band"><div class="band-inner"><h2>¿Y qué cuenta quien pasó por allí?</h2><p>Hay testimonios útiles y mucho escaparate. Las experiencias independientes son pequeñas y no comparables; las institucionales están seleccionadas. Léelas para hacer mejores preguntas.</p></div></section><section class="wrap" id="voces"><div class="voices">${D.voices.map(v=>`<article class="voice"><p class="voice-meta">${E(v.type)}<br>${E(v.date)}</p><h3>${E(v.name)}</h3><p><strong>Lo que valoran:</strong> ${E(v.up)}</p><p><strong>Lo que chirría o no sabemos:</strong> ${E(v.down)}</p><p class="limit">${E(v.limit)}</p>${link(v.url,'Leer la fuente original')}</article>`).join('')}</div></section><section class="wrap" id="fuentes"><p class="eyebrow">El alcance real de esta edición</p><h2>${D.institutions.length} instituciones.<br>Un mapa amplio, con límites.</h2><p>La edición reúne ${D.programs.length} rutas y ${sources.size} enlaces de referencia: investigación y predoc, multilaterales, bancos, UE, think tanks, tecnología y medición social. Europa es el centro; incluimos instituciones globales y vías relevantes fuera de Europa. No es un censo de todas las empresas del mundo.</p><details open><summary>Qué se ha buscado y cómo se ha contrastado</summary><p>Se buscaron portales oficiales de careers, internships, graduate programmes, traineeships, research assistantships y fellowships; unidades de investigación social, económica y computacional; y testimonios públicos identificables. Las fichas sintetizan información de páginas oficiales y, cuando corresponde, de convocatorias históricas. No se ha leído íntegramente cada documento de cada sitio. Algunas páginas restringen la extracción automática: no se considera un bloqueo técnico prueba de que el programa haya desaparecido.</p></details><details><summary>Programa, destino y canal: tres cosas diferentes</summary><p>«Programa» significa una vía estructurada documentada, con recurrencia descrita por la institución o ediciones anteriores. Eso no garantiza una futura edición. «Destino» participa en otro programa: EEA recibe trainees por Blue Book. «Canal» identifica contratación por equipos o proyectos, sin inventar un programa fijo ni listar puestos abiertos.</p></details><details><summary>Etapa, dinero y requisitos: lo que sigue por confirmar</summary><p>Las condiciones se conservan en palabras: no calculamos tu elegibilidad ni tu probabilidad de admisión. Los requisitos de matrícula, nacionalidad, visado, edad, título, idiomas y experiencia cambian entre vías. «Pago por confirmar» significa que esta ficha no acredita una condición uniforme. Las fuentes históricas se identifican cuando sirven para documentar una trayectoria.</p></details><details><summary>Una web estática, con fecha y sin vigilancia de vacantes</summary><p>El corte editorial es el 30 de septiembre de 2026. La web carga un catálogo local; no consulta ofertas, no anuncia plazas abiertas y no tiene scrapers periódicos ni tareas programadas. Los enlaces te llevan al programa o al portal de contratación para que lo consultes tú. El despliegue sólo publica cambios que se hagan en el repositorio.</p></details><details><summary>Acceso, derechos y opiniones</summary><p>Las referencias son públicas, pero algunos sitios pueden pedir acceso o impedir consultas automatizadas. El texto de las fichas es una síntesis original. No se redistribuyen los documentos completos, reseñas ni materiales de terceros. El tono informal expresa orientación editorial; no presenta rumores como hechos ni testimonios seleccionados como consenso.</p></details><div class="toolbar" style="margin-top:25px"><a href="fuentes.txt" download class="button coral small">Descargar bibliografía →</a><a href="catalogue.js" class="button small" target="_blank" rel="noopener noreferrer">Ver catálogo estático ↗</a></div><h3>Fuentes por institución</h3><ul class="sources-list">${D.institutions.map(i=>`<li>${link(i.url,i.name)}<small>${E(groupName(i.group))} · ${E(i.country)}</small></li>`).join('')}</ul><p class="legal-note">Cada ficha enlaza su fuente específica; los portales de contratación se distinguen cuando son diferentes. Si cambia una condición, manda la convocatoria oficial.</p></section>`;
  }

  function openProgram(id) {
    const p=programs.get(id); if(!p)return openMissing();const i=institutions.get(p.institution);
    const facts=[['Etapa',stage[p.stage]],['Tipo',kind[p.kind]],['Lugar',p.location],['Duración',p.duration],['Pago',pay[p.pay]],['Prioridad editorial',priority[p.priority]]];
    document.querySelector('#detail-content').innerHTML=`<header class="detail-head"><p class="eyebrow">${E(i.name)} · ${E(groupName(p.group))}</p><h2 id="detail-title">${E(p.name)}</h2><p>${p.themes.map(t=>E(D.themes[t])).join(' · ')}</p><button class="close-detail" aria-label="Cerrar ficha" data-close>×</button></header><div class="detail-body"><dl class="detail-facts">${facts.map(([k,v])=>`<div><dt>${k}</dt><dd>${E(v)}</dd></div>`).join('')}</dl><section class="detail-section"><h3>Mi lectura para tu PhD</h3><p>${E(p.fit)}</p><p class="legal-note">Valoración editorial: el puesto concreto debe darte investigación, métodos y supervisión que puedas demostrar. No es una recomendación oficial de Oxford o LSE.</p></section><div class="detail-columns"><section class="detail-section"><h3>Quién puede entrar</h3><p>${E(p.eligibility)}</p><h3>Qué preparar</h3><p>${E(p.docs)}</p></section><section class="detail-section"><h3>Cómo suele funcionar</h3><p>${E(p.rhythm)}</p><h3>Ojo con esto</h3><p>${E(p.watch)}</p></section></div><section class="detail-section"><h3>¿Y quién demonios es ${E(i.name)}?</h3><p>${E(i.intro)}</p><p><strong>Para situarla:</strong> ${E(i.comparison)}</p><a href="#institucion/${i.id}">Ver la institución y todas sus rutas →</a></section><section class="detail-section">${link(p.url,p.kind==='canal'?'Evidencia del canal':'Fuente y reglas del programa','button coral small')}${p.portal?link(p.portal,'Consultar contratación','button small'):''}${compareButton(p)}<p class="legal-note">Revisión editorial: 30/09/2026. Consulta reglas y plazas en la fuente. No se registra disponibilidad actual.</p></section></div>`;
    showDialog();
  }
  function openInstitution(id) {
    const i=institutions.get(id);if(!i)return openMissing();const list=D.programs.filter(p=>p.institution===id);
    document.querySelector('#detail-content').innerHTML=`<header class="detail-head"><p class="eyebrow">${E(groupName(i.group))} · ${E(i.country)}</p><h2 id="detail-title">${E(i.name)}</h2><p>${E(i.city)}</p><button class="close-detail" aria-label="Cerrar ficha" data-close>×</button></header><div class="detail-body"><section><h3>Qué es y por qué debería importarte</h3><p>${E(i.intro)}</p></section><section class="detail-section"><h3>Mi veredicto</h3><p>${E(i.verdict)}</p><p><strong>Cómo la compararía:</strong> ${E(i.comparison)}</p></section><div class="detail-columns"><section class="detail-section"><h3>Lo que tiene a favor</h3><p>${E(i.upside)}</p></section><section class="detail-section"><h3>Lo que puede darte pereza</h3><p>${E(i.downside)}</p></section></div><section class="detail-section"><h3>Sus rutas en este mapa</h3><div class="detail-programs">${list.map(p=>`<a href="#programa/${p.id}">${E(p.name)}<small>${kind[p.kind]} · ${stage[p.stage]} · ${pay[p.pay]}</small></a>`).join('')}</div></section><section class="detail-section"><h3>Sobre su reputación</h3><p>La valoración de esta ficha es editorial. No hay una muestra representativa que permita describir qué opina «la gente» de cada institución. Las voces públicas disponibles tienen su procedencia y sus límites.</p><a href="#criterio">Leer las voces y el criterio →</a></section><section class="detail-section">${link(i.url,'Conocer la institución / vía','button coral small')}${i.portal?link(i.portal,'Portal de contratación','button small'):''}<p class="legal-note">Corte editorial 30/09/2026. Compara tareas, supervisión y condiciones en cada convocatoria.</p></section></div>`;
    showDialog();
  }
  function openMissing() {document.querySelector('#detail-content').innerHTML='<div class="detail-body"><h2 id="detail-title">No encontramos esa ficha.</h2><p>Vuelve al catálogo para consultar las rutas de esta edición.</p><button data-close>Cerrar ficha</button></div>';showDialog();}
  function showDialog(){if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
  function closeDetail(){if(dialog.open){closing=true;dialog.close();closing=false;}restoreDetailFocus=true;location.hash=returnHash;}

  function render() {
    const route=path();const q=params();
    if(route.startsWith('programa/')||route.startsWith('institucion/')){
      if(!main.innerHTML)renderExplorer();
      route.startsWith('programa/')?openProgram(route.slice(9)):openInstitution(route.slice(12));
      document.title=(document.querySelector('#detail-title')?.textContent||'Ficha')+' · Social Data Club';
    }else{
      if(dialog.open){closing=true;dialog.close();closing=false;}
      ({guia:renderGuide,explorar:renderExplorer,comparar:renderCompare,criterio:renderCriteria}[route]||renderGuide)();
      document.title=({guia:'El mapa antes del PhD',explorar:'Programas y rutas',comparar:'Comparar rutas',criterio:'Voces y criterio'}[route]||'El mapa')+' · Social Data Club';
      if(route==='guia'&&q.has('familia'))document.querySelector('#familia')?.scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo({top:0,behavior:'instant'});
      if(restoreDetailFocus){
        const origin=[...main.querySelectorAll('a')].find(a=>a.getAttribute('href')===detailOrigin);
        (origin||main).focus({preventScroll:true});window.scrollTo({top:detailScroll,behavior:'instant'});restoreDetailFocus=false;
      }
    }
    updateNav();
  }
  document.addEventListener('click',e=>{
    const target=e.target.closest('button,a');if(!target)return;
    if(target.matches('a[href="#main"]')){e.preventDefault();main.focus();main.scrollIntoView({behavior:'instant'});return;}
    if(target.matches('a[href^="#programa/"],a[href^="#institucion/"]')&&!path().includes('/')){returnHash=location.hash||'#guia';detailOrigin=target.getAttribute('href');detailScroll=window.scrollY;}
    if(target.dataset.family)location.hash='guia?familia='+target.dataset.family;
    if(target.hasAttribute('data-close'))closeDetail();
    if(target.hasAttribute('data-clear'))clearFilters();
    if(target.hasAttribute('data-clear-compare')){selected.clear();renderCompare();updateNav();}
    if(target.dataset.remove){selected.delete(target.dataset.remove);renderCompare();updateNav();}
    if(target.dataset.compare){
      const id=target.dataset.compare;
      if(selected.has(id))selected.delete(id);else if(selected.size<3)selected.add(id);else return notify('Puedes comparar hasta tres rutas. Quita una para añadir otra.');
      document.querySelectorAll('[data-compare]').forEach(b=>{const yes=selected.has(b.dataset.compare);b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'✓ Añadido':'+ Comparar';b.setAttribute('aria-label',`${yes?'Quitar de':'Añadir a'} comparación: ${programs.get(b.dataset.compare).name}`);});
      const slot=document.querySelector('#tray-slot');if(slot)slot.innerHTML=tray();updateNav();
    }
  });
  dialog.addEventListener('cancel',e=>{e.preventDefault();closeDetail();});
  dialog.addEventListener('close',()=>{if(!closing&&path().includes('/'))location.hash=returnHash;});
  dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail();}});
  window.addEventListener('hashchange',render);
  render();
})();
